+  Assert.ok(
+    !!parent1.getChildNamed(child.name),
+    `${child.name} should exist in ${parent1.name}`
   );
   Assert.ok(
-    !!parent2.getChildNamed(childName),
-    `${childName} should exist in ${parent2Name}`
+    !!parent2.getChildNamed(child.name),
